"use client";

import React, { useEffect, useRef, useState } from "react";

/* ============================================================
   Night scene, built from raster images embedded in this file as
   base64 (AVIF first, WebP fallback). The data itself lives in the
   NIGHT_IMG object at the very bottom of the file. That includes the
   faint blue circuit / HUD plate (circuitAvif + circuitWebp) that sits
   between the photo and the vignette.
   ============================================================ */
/* Floating lanterns circling the gate. dx = offset from centre (desktop),
   dxm = offset on phones, by = height from the bottom, s = size multiplier. */
const LANTERNS = [
  { dx: "-25vw", dxm: "-33vw", by: "10%", s: 1,   flip: false, d: 0 },
  { dx: "-33vw", dxm: "-43vw", by: "27%", s: .72, flip: true,  d: -3 },
  { dx: "-20vw", dxm: "0",     by: "22%", s: .5,  flip: false, d: -6, far: true },
  { dx: "26vw",  dxm: "34vw",  by: "13%", s: .92, flip: true,  d: -2 },
  { dx: "33vw",  dxm: "43vw",  by: "31%", s: .66, flip: false, d: -5 },
  { dx: "20vw",  dxm: "0",     by: "24%", s: .48, flip: true,  d: -8, far: true },
];

function Lantern({ dx, dxm, by, s, flip, d, far }) {
  return (
    <div
      className={`lantern-rig${far ? " lantern-far" : ""}`}
      style={{ "--dx": dx, "--dxm": dxm, "--by": by, "--s": s, "--flip": flip ? -1 : 1, "--d": `${d}s` }}
      aria-hidden="true"
    >
      <div className="lantern-glow" />
      <picture>
        <source type="image/avif" srcSet={NIGHT_IMG.lanternAvif} />
        <img className="lantern-swing" src={NIGHT_IMG.lanternWebp} alt="" width="360" height="468" decoding="async" />
      </picture>
    </div>
  );
}

function NightScene() {
  return (
    <>
      <picture>
        <source type="image/avif" srcSet={NIGHT_IMG.sceneAvif} />
        <img className="night-photo" src={NIGHT_IMG.sceneWebp} alt="" width="2400" height="1350" decoding="async" />
      </picture>
      <picture>
        <source type="image/avif" srcSet={NIGHT_IMG.circuitAvif} />
        <img className="circuit-bg" src={NIGHT_IMG.circuitWebp} alt="" width="2400" height="1350" decoding="async" aria-hidden="true" />
      </picture>
      {LANTERNS.map((l, i) => <Lantern key={i} {...l} />)}
    </>
  );
}

/* Static stick-figure marathon runner that sits inside the word HACK|ATHON. */
function Runner() {
  return (
    <svg className="runner" viewBox="0 0 40 56" aria-hidden="true" focusable="false">
      <g fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="23.9" cy="7.3" r="4.6" />
        <path d="M23.1 12.2 L20 32" />
        <path d="M22.5 16.2 L27.4 23.7 L33.5 20" />
        <path d="M22.5 16.2 L15.9 22.3 L17 31" />
        <path d="M20 32 L27.4 41.5 L32.7 52.3 L37 52.3" />
        <path d="M20 32 L13.6 42.2 L3.4 35.8 L4.2 39.6" />
      </g>
    </svg>
  );
}

export default function HeroComponent() {
  const [pageVisible, setPageVisible] = useState(true);
  const [motionAllowed, setMotionAllowed] = useState(true);
  const [inView, setInView] = useState(true);
  const heroRef = useRef(null);
  const [clock, setClock] = useState("--:--:--");

  useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");

    const updateMotion = () => setMotionAllowed(!media.matches);
    const updateVisibility = () => setPageVisible(!document.hidden);

    updateMotion();
    updateVisibility();

    media.addEventListener("change", updateMotion);
    document.addEventListener("visibilitychange", updateVisibility);

    return () => {
      media.removeEventListener("change", updateMotion);
      document.removeEventListener("visibilitychange", updateVisibility);
    };
  }, []);

  // Pause every animation (canvases, CSS, clock) once the hero has scrolled out of view.
  useEffect(() => {
    const el = heroRef.current;
    if (!el || typeof IntersectionObserver === "undefined") return undefined;
    const io = new IntersectionObserver(([entry]) => setInView(entry.isIntersecting), { rootMargin: "80px" });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  // Live Tokyo clock for the status bar (stops while the hero is off-screen).
  useEffect(() => {
    if (!inView) return undefined;
    const fmt = new Intl.DateTimeFormat("en-GB", {
      timeZone: "Asia/Tokyo", hour12: false, hour: "2-digit", minute: "2-digit", second: "2-digit",
    });
    const tick = () => setClock(fmt.format(new Date()));
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [inView]);

  const animate = pageVisible && motionAllowed && inView;

  return (
    <section
      ref={heroRef}
      className={`living-hero motion-${animate ? "active" : "paused"}`}
    >
      {/* Night scene background */}
      <div className="city-background" aria-hidden="true">
        <NightScene />
        <div className="city-vignette" />
      </div>

      {/* Centered hero content */}
      <div className="hero-core">
        <div className="institution">
          <div className="inst-item">
            <span className="inst-text"><span className="live-dot" />PES UNIVERSITY</span>
          </div>
          <span className="institution-divider">/</span>
          <div className="inst-item">
            <span className="inst-text">DEPARTMENT OF CSE</span>
          </div>
        </div>

        <div className="signal-label">
          <span />
          AN EXPERIMENT IN WHAT'S POSSIBLE
          <span />
        </div>

        <h1 className="main-title">
          <span>KODIKON</span>
          <span className="title-version">6.0</span>
        </h1>

        <p className="hero-subtitle">
          24-HOUR FLAGSHIP <span>NATIONAL HACK<Runner />ATHON</span>
        </p>

        <p className="hero-copy">
          Ten million lights. One connected city. Everything begins with an idea.
        </p>
      </div>

      <div className="bottom-status">
        <span className="status-online"><span /> SYSTEM ONLINE</span>
        <span className="status-center">
          {"EDO " + clock + " JST"}
        </span>
        <span>BUILD / BREAK / REPEAT</span>
      </div>

      <style>{`
        /* ============================================================
           KODIKON hero: single consolidated stylesheet
           --u is 1% of the hero height, so type and car scale with the
           screen height and the whole scene fits in one viewport.
           Set --nav-h to your navbar height (0px if there is none).
           ============================================================ */
        .living-hero {
          /* The Embrione design system */
          --canvas: #000000;
          --navy: #000514;
          --surface: #161617;
          --surface-hi: #1d1d1f;
          --slate: #0f172a;
          --divider: #1e293b;
          --blue: #0071e3;
          --blue-hi: #0077ed;
          --cyan: #22d3ee;
          --cyan-deep: #06b6d4;
          --cyan-dark: #0891b2;
          --text: #ffffff;
          --text-2: #a1a1a6;
          --text-3: #6e6e73;
          --line: rgba(255,255,255,.08);
          --line-hi: rgba(255,255,255,.2);
          --pink: #0071e3;   /* secondary accent = Accent Blue */
          --purple: #0891b2; /* tertiary accent = Cyan Dark */
          --nav-h: 62px;
          --hero-h: max(560px, calc(100vh - var(--nav-h)));
          --u: calc(var(--hero-h) / 100);
          position: relative;
          box-sizing: border-box;
          isolation: isolate;
          display: flex;
          flex-direction: column;
          justify-content: center;
          height: var(--hero-h);
          padding-bottom: 46px;
          overflow: hidden;
          background: #000000;
          color: #ffffff;
          font-family: Inter, ui-sans-serif, system-ui, sans-serif;
        }

        @supports (height: 100svh) {
          .living-hero { --hero-h: max(560px, calc(100svh - var(--nav-h))); }
        }

        .living-hero * { box-sizing: border-box; }

        /* ---------- Background: image plate, then light and shadow on top ---------- */
        .city-background {
          position: absolute;
          inset: 0;
          z-index: -1;
          overflow: hidden;
          background: #00040e;
        }
        .night-photo {
          position: absolute;
          inset: 0;
          width: 100%;
          height: 100%;
          object-fit: cover;
          object-position: 50% 62%;
          display: block;
        }

        /* Faint blue circuit / HUD plate, sits between the photo and the vignette */
        .circuit-bg {
          position: absolute;
          inset: 0;
          width: 100%;
          height: 100%;
          object-fit: cover;
          object-position: 50% 50%;
          display: block;
          opacity: .2;
          mix-blend-mode: screen;
          pointer-events: none;
          user-select: none;
        }

        /* Floating lanterns drifting around the gate */
        .lantern-rig {
          position: absolute;
          left: calc(50% + var(--dx));
          bottom: var(--by);
          width: calc(var(--s) * clamp(84px, 8.5vw, 140px));
          transform: translateX(-50%);
          pointer-events: none;
        }
        .lantern-swing {
          position: relative;
          display: block;
          width: 100%;
          height: auto;
          opacity: .9;
          transform: scaleX(var(--flip));
          animation: lantern-bob 8s ease-in-out var(--d) infinite alternate;
        }
        /* cold spill onto the mist and the gate, centred on the paper */
        .lantern-glow {
          position: absolute;
          top: 42%;
          left: 50%;
          width: 560%;
          aspect-ratio: 1;
          transform: translate(-50%, -50%);
          background: radial-gradient(circle, rgba(70,160,235,.15) 0%, rgba(20,90,170,.06) 24%, rgba(0,30,90,.02) 44%, transparent 60%);
          animation: lantern-flicker 6s ease-in-out var(--d) infinite alternate;
        }

        .city-vignette {
          position: absolute;
          inset: 0;
          background:
            radial-gradient(ellipse at 50% 52%, transparent 40%, rgba(0,2,8,.62) 100%),
            linear-gradient(180deg, rgba(0,2,8,.35), transparent 20%, transparent 72%, #000514 100%);
        }

        @media (max-width: 760px) {
          .lantern-rig { left: calc(50% + var(--dxm)); width: calc(var(--s) * 64px); }
          .lantern-far { display: none; }
          .night-photo { object-position: 50% 70%; }
          .circuit-bg { opacity: .16; }
        }

        /* ---------- Hero content (everything scales with --u) ---------- */
        .hero-core {
          position: relative;
          z-index: 3;
          display: flex;
          flex-direction: column;
          align-items: center;
          width: min(1100px, 96%);
          margin: 0 auto;
          text-align: center;
          transform: translateY(-10vh);
          transition: transform .7s cubic-bezier(.2,.8,.2,1);
        }

        .is-unlocked .hero-core {
          transform: translateY(-2vh) scale(.78);
          transform-origin: top center;
        }

        .institution {
          display: flex;
          align-items: center;
          justify-content: center;
          gap: .8em;
          padding: .8em 1.3em;
          border: 1px solid #1e293b;
          border-radius: 3px;
          background: #0f172a;
          backdrop-filter: blur(14px);
          color: #cbd5e1;
          font: 600 clamp(11px, calc(var(--u) * 2.1), 13.5px) ui-monospace, monospace;
          letter-spacing: .08em;
        }

        .live-dot, .status-online > span {
          width: 7px;
          height: 7px;
          flex: 0 0 auto;
          border-radius: 50%;
          background: var(--cyan);
          box-shadow: 0 0 12px var(--cyan);
          animation: dot-pulse 2s infinite;
        }
        .institution-divider { color: var(--pink); align-self: center; }
        .inst-item { display: flex; flex-direction: column; align-items: center; gap: .7em; }
        .inst-text { display: inline-flex; align-items: center; gap: .8em; text-align: center; }

        .signal-label {
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 12px;
          margin-top: clamp(10px, calc(var(--u) * 2.6), 26px);
          color: var(--cyan);
          font: 600 clamp(11px, calc(var(--u) * 2.2), 14px) ui-monospace, monospace;
          letter-spacing: .18em;
        }
        .signal-label > span {
          width: clamp(20px, 3vw, 40px);
          height: 1px;
          background: var(--cyan);
          opacity: .7;
        }

        .main-title {
          display: flex;
          align-items: baseline;
          justify-content: center;
          flex-wrap: wrap;
          gap: clamp(8px, 1.2vw, 18px);
          margin: 6px 0 0;
          font-size: clamp(48px, min(calc(var(--u) * 15), 9.6vw), 128px);
          font-weight: 950;
          line-height: .92;
          letter-spacing: -.085em;
        }
        .title-version {
          color: transparent;
          -webkit-text-stroke: 2px var(--cyan);
        }

        .hero-subtitle {
          margin: clamp(8px, calc(var(--u) * 2), 20px) 0 0;
          color: #ffffff;
          font: 500 clamp(14px, calc(var(--u) * 3.3), 22px) ui-monospace, monospace;
          letter-spacing: .04em;
        }
        .hero-subtitle span { color: var(--cyan); }

        /* Marathon runner inside the word HACKATHON (static) */
        .runner {
          display: inline-block;
          height: 1.7em;
          width: auto;
          margin: -.6em .08em;
          vertical-align: -.32em;
          overflow: visible;
          color: var(--cyan);
        }

        .hero-copy {
          max-width: 720px;
          margin: clamp(6px, calc(var(--u) * 1.2), 14px) auto 0;
          color: #a1a1a6;
          font-size: clamp(17px, calc(var(--u) * 3.5), 22px);
          line-height: 1.5;
          text-wrap: balance;
        }

        .enter-button, .reset-button {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          gap: 12px;
          margin-top: clamp(12px, calc(var(--u) * 2.6), 24px);
          padding: .95em 1.7em;
          border: 1px solid #06b6d4;
          background: #06b6d4;
          color: #000514;
          font: 800 clamp(12px, calc(var(--u) * 2.5), 14px) ui-monospace, monospace;
          letter-spacing: .12em;
          cursor: pointer;
          clip-path: polygon(0 0, 91% 0, 100% 28%, 100% 100%, 9% 100%, 0 72%);
          transition: transform .2s, box-shadow .2s, background .2s;
        }
        .enter-button:hover, .enter-button:focus-visible {
          outline: none;
          transform: translateY(-3px);
          background: #22d3ee;
          border-color: #22d3ee;
        }
        .button-arrow { font-size: 1.25em; }

        .reset-button {
          background: #0f172a;
          color: var(--cyan);
          clip-path: none;
          border-color: #1e293b;
        }
        .reset-button:hover { background: #1d1d1f; }

        .bottom-status {
          position: absolute;
          right: 0;
          bottom: 14px;
          left: 0;
          z-index: 7;
          display: flex;
          justify-content: space-between;
          gap: 12px;
          padding: 0 4%;
          color: #6e6e73;
          font: 600 10px ui-monospace, monospace;
          letter-spacing: .1em;
        }
        .status-online { display: flex; align-items: center; gap: 8px; color: #22d3ee; }

        /* ---------- Motion control ---------- */
        .motion-paused *, .motion-paused *::before, .motion-paused *::after { animation-play-state: paused !important; }

        @media (prefers-reduced-motion: reduce) {
          .ai-caret { animation: none !important; }
          .living-hero *, .living-hero *::before, .living-hero *::after {
            animation-duration: .01ms !important;
            animation-iteration-count: 1 !important;
            scroll-behavior: auto !important;
          }
        }

        /* ---------- Phones: cards zig-zag left / right / left ---------- */
        @media (max-width: 760px) {
          .living-hero { --hero-h: max(640px, calc(100vh - var(--nav-h))); padding-bottom: 40px; }
          @supports (height: 100svh) {
            .living-hero { --hero-h: max(640px, calc(100svh - var(--nav-h))); }
          }

          /* Locked: one screen. Unlocked: taller page so the cards can zig-zag down it. */
          .living-hero.is-unlocked {
            height: auto;
            min-height: 1020px;
            justify-content: flex-start;
            padding-top: 36px;
          }
          .is-unlocked .hero-core { transform: translateY(-10px) scale(.88); }

          .hero-core { width: min(1100px, 96%); margin: 0 auto; }

          .institution { font-size: 11px; padding: .7em 1em; }
          .signal-label { font-size: 10.5px; letter-spacing: .12em; }
          .signal-label > span { width: 16px; }
          .main-title { font-size: clamp(44px, 13vw, 76px); gap: 8px; }
          .hero-subtitle { font-size: clamp(13px, 3.6vw, 17px); }
          .hero-copy { font-size: 17px; padding-inline: 12px; }
          .coordinates { font-size: 10px; gap: 8px; }
          .bottom-status { bottom: 12px; font-size: 9px; }
          .status-center { display: none; }

        }

        @media (max-width: 380px) {
          .institution { gap: 5px; font-size: 9.5px; }
          .main-title { font-size: 44px; }
        }

        /* ---------- Keyframes ---------- */
        @keyframes glow-breathe {
          from { opacity: .1; }
          to { opacity: .2; }
        }
        @keyframes dot-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }
        @keyframes orbit-spin { to { transform: rotate(360deg); } }
        @keyframes ai-caret { 50% { opacity: 0; } }
        @keyframes lantern-bob { from { translate: 0 -7px; rotate: -1.5deg; } to { translate: 0 7px; rotate: 1.5deg; } }
        @keyframes lantern-flicker { from { opacity: .8; } to { opacity: 1; } }
      `}</style>
    </section>
  );
}

/* ---------- Embedded images (base64) ---------- */
const NIGHT_IMG = {
  circuitAvif: "data:image/avif;base64,",
  circuitWebp: "data:image/webp;base64,",
  sceneAvif: "data:image/avif;base64,",
  sceneWebp: "data:image/webp;base64,",
  lanternAvif: "data:image/avif;base64,",
  lanternWebp: "data:image/webp;base64,",
};
